"islamic-656-first-fitna-begins-23":{title:"הפִתנה הראשונה מתחילה",location:"הח'ליפות",story:"רצח עות'מאן הצית את מלחמת האזרחים המוסלמית הגדולה הראשונה סביב לגיטימיות פוליטית, דרישה לצדק על רצח הח'ליף וסמכות ח'ליפותו של עלי.",context:"מלחמת אזרחים מוסלמית",aftermath:"העימות שבר את האחדות הפוליטית של הקהילה המוסלמית והשפיע עמוקות על מחלוקות מאוחרות בדבר הנהגה ולגיטימיות.",sourceStatus:"הפִתנה הראשונה היא אירוע היסטורי; נרטיבים סוניים ושיעיים מאוחרים מייחסים אחריות ולגיטימיות באופן שונה."},
"islamic-656-caliph-uthman-assassinated-24":{title:"הח'ליף עות'מאן נרצח",location:"מדינה",story:"מורדים הרגו את עות'מאן במדינה לאחר התנגדות גוברת לממשלו. מותו שבר את הקונצנזוס הפוליטי והוביל מיד לפִתנה הראשונה.",context:"התנקשות פוליטית / גורם למלחמת אזרחים",aftermath:"רציחתו נעשתה מוקד מרכזי במאבק על סמכותו של עלי ובדרישות לנקום את דמו של עות'מאן.",sourceStatus:"ההתנקשות היסטורית; מסורות עדתיות מאוחרות חלוקות מאוד בשאלת האשמה."},
"islamic-656-battle-of-the-camel-25":{title:"קרב הגמל",location:"בצרה",story:"כוחות המזוהים עם הח'ליף עלי הביסו ליד בצרה צבא שהיה קשור לעאישה, טלחה ואל־זובייר במהלך הפִתנה הראשונה.",context:"מלחמת אזרחים מוסלמית",aftermath:"הקרב חיזק זמנית את מעמדו של עלי אך העימות עם מועאוויה בסוריה נמשך.",sourceStatus:"הקרב היסטורי. המסורות הסונית והשיעית המאוחרות זוכרות ומעריכות את הדמויות המרכזיות בו בדרכים שונות."}
